examples.code:
VStack(spacing: 0) {
    ZStack(alignment: .bottom) {
        theme.colors.bgMuted
        MonarchAvatar(image: nil, name: "Robin Park", size: .xl, isDecorative: true)
            .padding(4)
            .overlay(Circle().strokeBorder(theme.colors.successBorder, lineWidth: 3))
            .frame(maxHeight: .infinity)
        HStack {
            Text("Robin Park")
                .monarchTextStyle(.caption)
                .foregroundStyle(Color.white)
            Spacer(minLength: 0)
            Image(systemName: "cellularbars")
                .foregroundStyle(theme.colors.successSolid)
        }
        .padding(.horizontal, theme.spacing.space2)
        .frame(height: 24)
        .background(RoundedRectangle(cornerRadius: 4).fill(Color.black.opacity(0.85)))
        .padding(.horizontal, 6)
        .padding(.bottom, 6)
    }
    .frame(height: 128)
    Rectangle()
        .fill(theme.colors.successSolid)
        .frame(height: 2)
    HStack(spacing: theme.spacing.space2) {
        Text("12:00")
            .monarchTextStyle(.caption)
            .foregroundStyle(theme.colors.textMuted)
        Text("4 in call")
            .monarchTextStyle(.caption)
            .foregroundStyle(theme.colors.textMuted)
        Spacer(minLength: 0)
        Button {
        } label: {
            Image(systemName: "mic")
                .foregroundStyle(theme.colors.textDefault)
                .frame(width: 32, height: 32)
                .background(Circle().fill(theme.colors.bgMuted))
        }
        .accessibilityLabel("Mute")
        Button {
        } label: {
            Image(systemName: "arrow.up.left.and.arrow.down.right")
                .foregroundStyle(theme.colors.textDefault)
                .frame(width: 32, height: 32)
                .background(Circle().fill(theme.colors.bgMuted))
        }
        .accessibilityLabel("Back to the call")
        Button {
        } label: {
            Image(systemName: "phone.down.fill")
                .foregroundStyle(theme.colors.dangerOnSolid)
                .frame(width: 32, height: 32)
                .background(Circle().fill(theme.colors.dangerSolid))
        }
        .accessibilityLabel("Leave")
    }
    .padding(theme.spacing.space2)
    .background(theme.colors.bgSurface)
}
.frame(width: 240)
.clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
.shadow(color: .black.opacity(0.15), radius: 12, y: 4)
.frame(maxWidth: .infinity)
